/// `thread/resume` responses and live `thread/settings/updated` notifications;
/// every field is `None` when the server hasn't said (never a guess).
class ThreadRuntimeConfigDto {
  /// Effective model id.
  final String? model;

  /// Provider of the effective model.
  final String? modelProvider;

  /// Effective reasoning effort.
  final String? reasoningEffort;

  /// Effective approval policy.
  final String? approvalPolicy;

  /// Approval reviewer (`user` or `auto_review`), when reported.
  final String? approvalsReviewer;

  /// Effective service tier, when reported.
  final String? serviceTier;

  /// Effective sandbox mode (kebab wire string).
  final String? sandboxMode;

  /// Effective collaboration mode (`plan`/`default`), when reported.
  final String? collaborationMode;

  /// True once a live settings update confirmed this config.
  final bool confirmedByUpdate;

  const ThreadRuntimeConfigDto({
    this.model,
    this.modelProvider,
    this.reasoningEffort,
    this.approvalPolicy,
    this.approvalsReviewer,
    this.serviceTier,
    this.sandboxMode,
    this.collaborationMode,
    required this.confirmedByUpdate,
  });

  @override
  int get hashCode =>
      model.hashCode ^
      modelProvider.hashCode ^
      reasoningEffort.hashCode ^
      approvalPolicy.hashCode ^
      approvalsReviewer.hashCode ^
      serviceTier.hashCode ^
      sandboxMode.hashCode ^
      collaborationMode.hashCode ^
      confirmedByUpdate.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ThreadRuntimeConfigDto &&
          runtimeType == other.runtimeType &&
          model == other.model &&
          modelProvider == other.modelProvider &&
          reasoningEffort == other.reasoningEffort &&
          approvalPolicy == other.approvalPolicy &&
          approvalsReviewer == other.approvalsReviewer &&
          serviceTier == other.serviceTier &&
          sandboxMode == other.sandboxMode &&
          collaborationMode == other.collaborationMode &&
          confirmedByUpdate == other.confirmedByUpdate;
}

/// A selected turn's bounded, ascending history window.
class TurnItemsPageDto {
  /// Turn owning the window.
  final String turnId;

  /// Loaded items in chronological order.
  final List<ThreadItemDto> items;

  /// Whether this turn still has a continuation page.
  final bool hasMore;

  const TurnItemsPageDto({
    required this.turnId,
    required this.items,
    required this.hasMore,
  });

  @override
  int get hashCode => turnId.hashCode ^ items.hashCode ^ hasMore.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TurnItemsPageDto &&
          runtimeType == other.runtimeType &&
          turnId == other.turnId &&
          items == other.items &&
          hasMore == other.hasMore;
}

/// A turn reduced to what the rail shows.
class TurnSummaryDto {
  /// Id of the turn, for fetching its items on demand.
  final String turnId;

  /// The user's message that opened the turn; empty when it had none.
  final String userText;

  /// The turn's final agent message; empty when it produced no prose.
  final String assistantText;

  /// Whether this turn's items are already in the transcript.
  final bool loaded;

  const TurnSummaryDto({
    required this.turnId,
    required this.userText,
    required this.assistantText,
    required this.loaded,
  });

  @override
  int get hashCode =>
      turnId.hashCode ^
      userText.hashCode ^
      assistantText.hashCode ^
      loaded.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TurnSummaryDto &&
          runtimeType == other.runtimeType &&
          turnId == other.turnId &&
          userText == other.userText &&
          assistantText == other.assistantText &&
          loaded == other.loaded;
}
